// QueryForumStats queries the forum_stats edge of a Node.
func (c *NodeClient) QueryForumStats(_m *Node) *ForumStatsQuery {
	query := (&ForumStatsClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(node.Table, node.FieldID, id),
			sqlgraph.To(forumstats.Table, forumstats.FieldID),
			sqlgraph.Edge(sqlgraph.O2O, false, node.ForumStatsTable, node.ForumStatsColumn),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

